import { spawnSync } from "node:child_process";
import { runSyncChecked } from "./lib/run.ts";

export function checkApple(root: string, scope = "all") {
  if (!["all", "host", "app", "lint"].includes(scope))
    throw new Error("usage: pnpm apple check [host|app|lint]");
  const run = (program: string, args: string[]) =>
    runSyncChecked(program, args, root);
  if (scope === "all" || scope === "lint")
    run("pnpm", ["exec", "nx", "run", "apple:lint"]);
  if (scope === "lint") return;

  // Generated bytes participate in the pass key. FFI and Xcode project setup
  // do not run until a native task misses, so a cached pass needs no compiler.
  run(process.execPath, ["scripts/generator/ensure.ts"]);
  const targets =
    scope === "all"
      ? ["host-tests", "simulator-build"]
      : [scope === "host" ? "host-tests" : "simulator-build"];
  const missing = targets.filter((target) => {
    const result = spawnSync("pnpm", ["exec", "nx", "run", `apple:${target}`], {
      cwd: root,
      stdio: "inherit",
      env: { ...process.env, NX_DAEMON: "false", CUBBY_NX_CACHE_PROBE: "1" },
    });
    if (result.error) throw result.error;
    if (result.signal)
      throw new Error(`Apple cache probe interrupted by ${result.signal}`);
    return result.status !== 0;
  });
  if (missing.length === 0) return;
  // Prepare once outside Nx: nested calls from the two targets cannot acquire
  // the FFI artifact, and parallel native compiles contend on the local host.
  run(process.execPath, ["scripts/ensure-apple-ffi.ts"]);
  run("pnpm", [
    "exec",
    "nx",
    "run-many",
    "--projects=apple",
    `--targets=${missing.join(",")}`,
    "--parallel=1",
  ]);
}
